export const isPointInsideContour = (point: Point, entities: DxfEntity[], bbox: BoundingBox): boolean => {
    if (point.x < bbox.minX || point.x > bbox.maxX || point.y < bbox.minY || point.y > bbox.maxY) {
        return false;
    }

    let intersections = 0;

    const rayIntersectsSegment = (p: Point, a: Point, b: Point): boolean => {
        if ((a.y > p.y) !== (b.y > p.y)) {
            const intersectX = a.x + (p.y - a.y) * (b.x - a.x) / (b.y - a.y);
            if (intersectX > p.x) return true;
        }
        return false;
    };

    for (const entity of entities) {
        switch (entity.type) {
            case 'LWPOLYLINE': {
                const v = entity.vertices;
                for (let i = 0; i < v.length; i++) {
                    const p1 = v[i];
                    const p2 = v[(i + 1) % v.length];
                    if (!entity.closed && i === v.length - 1) continue;
                    if (rayIntersectsSegment(point, p1, p2)) intersections++;
                }
                break;
            }
            case 'LINE':
                if (rayIntersectsSegment(point, entity.start, entity.end)) intersections++;
                break;
            // Дополнительные проверки для CIRCLE/ARC могут быть вынесены в свои файлы при усложнении
        }
    }

    return intersections % 2 !== 0;
};

import { Point, Tool, NibbleSettings, PlacedTool, ToolShape } from '../../types/tooling';
import { generateId } from '../../utils/helpers';

export const generateNibblePunches = (
    p1: Point,
    p2: Point,
    tool: Tool,
    settings: NibbleSettings,
    angle: number,
    punchOrientation: number,
    punchOffset: number
): Omit<PlacedTool, 'id'>[] => {
    const punches: Omit<PlacedTool, 'id'>[] = [];
    const lineGroupId = `nibble_${generateId()}`;

    const dx = p2.x - p1.x;
    const dy = p2.y - p1.y;
    const length = Math.sqrt(dx * dx + dy * dy);

    if (length === 0) return [];

    const ux = dx / length;
    const uy = dy / length;
    const nx = -uy;
    const ny = ux;

    const effectiveLength = length + settings.extensionStart + settings.extensionEnd;
    if (effectiveLength <= 0.1) return [];

    const toolRad = (punchOrientation * Math.PI) / 180;
    const lineRad = (angle * Math.PI) / 180;
    const relativeAngle = Math.abs(lineRad - toolRad);

    let toolLength = tool.shape === ToolShape.Circle 
        ? tool.width 
        : tool.width * Math.abs(Math.cos(relativeAngle)) + tool.height * Math.abs(Math.sin(relativeAngle));

    const step = Math.max(0.1, toolLength - settings.minOverlap);
    const halfProj = toolLength / 2;

    const startX = p1.x - ux * settings.extensionStart;
    const startY = p1.y - uy * settings.extensionStart;

    const firstCenterX = startX + ux * halfProj + nx * punchOffset;
    const firstCenterY = startY + uy * halfProj + ny * punchOffset;

    const travelLength = effectiveLength - toolLength;
    const actualHits = travelLength <= 0 ? 1 : Math.ceil(travelLength / step) + 1;
    const adjustedStep = actualHits > 1 ? travelLength / (actualHits - 1) : 0;

    for(let i=0; i<actualHits; i++) {
        punches.push({
            toolId: tool.id,
            x: firstCenterX + ux * i * adjustedStep,
            y: firstCenterY + uy * i * adjustedStep,
            rotation: punchOrientation,
            lineId: lineGroupId
        });
    }
    return punches;
};

import { useCallback } from 'react';
import { Part, PlacedTool } from '../types/tooling';
import { generateId } from '../utils/helpers';

export const useAppActions = (
    activePart: Part | null, 
    setActivePart: (p: Part | null) => void,
    addToast: (msg: string, type: 'success' | 'error') => void
) => {

    const addPunches = useCallback((punchesData: Omit<PlacedTool, 'id'>[]) => {
        if (!activePart) return;
        const newPunches = punchesData.map(p => ({ ...p, id: generateId() }));
        setActivePart({ ...activePart, punches: [...activePart.punches, ...newPunches] });
    }, [activePart, setActivePart]);

    const deletePunches = useCallback((ids: string[]) => {
        if (!activePart) return;
        setActivePart({
            ...activePart,
            punches: activePart.punches.filter(p => !ids.includes(p.id))
        });
    }, [activePart, setActivePart]);

    const clearAllPunches = useCallback(() => {
        if (!activePart) return;
        setActivePart({ ...activePart, punches: [] });
        addToast("Все инструменты удалены", "success");
    }, [activePart, setActivePart, addToast]);

    return { addPunches, deletePunches, clearAllPunches };
};

